            ent_insn        <= 32'd0;
            ent_rob         <= 4'd0;
            ent_prs1        <= 6'd0;
            ent_prs2        <= 6'd0;
            ent_pdst        <= 6'd0;
            ent_rs1_ready   <= 1'b0;
            ent_rs2_ready   <= 1'b0;
            ent_is_load     <= 1'b0;
            ent_is_store    <= 1'b0;
            ent_epoch       <= 2'd0;
            ent_issued      <= 1'b0;
            ent_committed   <= 1'b0;
            req_active      <= 1'b0;
            req_we_q        <= 1'b0;
            req_addr_q      <= 32'd0;
            req_wdata_q     <= 32'd0;
            req_be_q        <= 4'd0;
            req_rob_q       <= 4'd0;
            req_epoch_q     <= 2'd0;
