                            (do_alloc && (alloc_slot[0] == 1'b0)) ? pdst_new :
                                                                    slot0_pdst;
    assign slot1_pdst_nxt = flush_elig[1] ? PR_ZERO :
                            (do_alloc && (alloc_slot[0] == 1'b1)) ? pdst_new :
