    assign slot0_old_nxt  = flush_elig[0] ? PR_ZERO :
                            (do_alloc && (alloc_slot[0] == 1'b0)) ? old_prd :
                                                                    slot0_old;
    assign slot1_old_nxt  = flush_elig[1] ? PR_ZERO :
                            (do_alloc && (alloc_slot[0] == 1'b1)) ? old_prd :
