                slot1_pdst <= slot1_pdst_nxt;
                slot0_old  <= slot0_old_nxt;
                slot1_old  <= slot1_old_nxt;
                slot0_rd   <= slot0_rd_nxt;
                slot1_rd   <= slot1_rd_nxt;
            end
            if (cur_tail_en)   cur_tail   <= cur_tail_nxt;
        end
    end

