    assign lsu_dcache_req_be        = req_active ? req_be_q : h_be;
    assign lsu_dcache_req_rob_index = req_active ? req_rob_q : h_rob;
    assign lsu_dcache_req_epoch     = req_active ? req_epoch_q : h_epoch;

