    always_ff @(posedge clk) begin
        if (!rst_n) begin
            cnt        <= 3'd0;
            head_ptr   <= 2'd0;
            e_valid    <= 4'd0;
            e_r1rdy    <= 4'd0;
            e_r2rdy    <= 4'd0;
            e_issued   <= 4'd0;
