                        (h_remove ? 3'd1 : 3'd0) - kill_cnt;
            if (h_remove) head_ptr <= head_ptr + 2'd1;

            // hold the external request until ready (one outstanding op)
            if (!req_active) begin
                if (h_can_issue && !lsu_dcache_req_ready) begin
                    req_active  <= 1'b1;
                    req_we_q    <= h_isstore;
                    req_addr_q  <= h_addr;
                    req_wdata_q <= h_wdata;
                    req_be_q    <= h_be;
                    req_rob_q   <= h_rob;
                    req_epoch_q <= h_epoch;
                end
            end else begin
                if (lsu_dcache_req_ready) req_active <= 1'b0;
            end
            if (squash_head) req_active <= 1'b0;
        end
    end

