    logic [0:0]  free_idx;
    logic        sel_exist;
    logic [0:0]  sel_idx;
    logic        disp_fire;
    logic        issue_fire;
    logic        bypass_fire;
    logic        disp_uses1;
    logic        disp_uses2;

    logic [IQ_DEPTH-1:0] flush_mask;
    logic [IQ_DEPTH-1:0] valid_next;
    logic [IQ_DEPTH-1:0] r1rdy_next;
