    assign slot0_rd_nxt   = flush_elig[0] ? 5'd0 :
                            (do_alloc && (alloc_slot[0] == 1'b0)) ? id_rd :
                                                                    slot0_rd;
    assign slot1_rd_nxt   = flush_elig[1] ? 5'd0 :
                            (do_alloc && (alloc_slot[0] == 1'b1)) ? id_rd :
